INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65883999', 65883999, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Obat TB Paru Sediaan Khusus Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 182117358531, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dengan Menyediakan Obat TB Tahap I dengan sediaan khusus Tahun 2026 berupa : 1. Pretomanid 200 mg sebanyak 1.758.276 Tablet/Kapsul/Kaplet dengan estimasi harga satuan Rp37.890 2. Bedaquiline 100 mg sebanyak 1.603.828 tablet/Kapsul/Kaplet dengan estimasi harga satuan Rp16.369 3. KDT 3HP sebanyak 5.505.565 dengan estimasi harga satuan Rp16.210', 'Spesifikasi umum untuk Obat Mempunyai izin edar dari Badan POM / SAS (Special Acces Scheme) 1. Pretomanid 200 mg: • Masa Kadaluwarsa/Expire Date: Shelflife lebih dari 24 bulan maka masa kedaluwarsa minimal 24 bulan, • Shelf life sama dengan 24 bulan maka kedaluwarsa minimal 18 bulan. • Jumlah tablet pembulatan keatas menyesuaikan kemasan. 2. Bedaquiline 100 mg: • Masa Kadaluwarsa/ Expire Date: Shelf life lebih dari 24 bulan maka masa kedaluwarsa minimal 24 bulan, • Shelf life sama dengan 24 bulan maka kedaluwarsa minimal 18 bulan. • Jumlah tablet pembulatan keatas menyesuaikan kemasan. Pada kemasan tersedia informasi sbb: 1. Tanggal Produksi 2. Tanggal kedaluarsa obat 3. Batch No. 4. Nama Pabrik/Produsen 3. KDT 3HP: a. Nama Produk : 3HP (Isoniazid Rifapentin) KDT 300 mg/300mg b. Bentuk Sediaan : Tablet/kaplet/kapsul c. Komposisi : KDT mengandung Isoniazid 300mg dan Rifapentin 300 mg d. Surat Pernyataan Masa Kadaluwarsa: Produk obat di atas mempunyai batas kadaluarsa minimal 24 bulan jika shelflife lebih dari 24 bulan, atau batas kadaluarsa minimal 18 bulan jika shelflife 24 bulan pada saat diterima di Instalasi Farmasi Pusat (IFP). e. Penyedia bersedia menyampaikan surat pernyataan pada kemasan tersedia informasi Tanggal Produksi, Tanggal Kedaluarsa Obat, Nomor Batch, Nama Pabrik/Produsen. f. Penyedia bersedia menyampaikan surat pernyataan memiliki Nomor Izin Edar (NIE) dari BPOM atau bersedia mengurus ijin Special Access Scheme (SAS) dari Kemenkes RI setelah ditetapkan sebagai pemenang. g. Jadwal dan jangka waktu pelaksanaan pekerjaan sampai dengan serah terima pekerjaan di Instalasi Farmasi Pusat sesuai alokasi distribusi. h. Surat pernyataan bahwa produk obat memiliki LOA/Surat Dukungan/Surat Perjanjian apabila produk obat merupakan produk impor. i. Gambar/foto/brosur produk/dokumen mutu seperti Certificate of Analysis (CoA) yang mendukung spesifikasi teknis produk yang ditawarkan. j. Penyedia bersedia menyampaikan Surat Pernyataan Kewajaran Harga', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2420655);
