INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65882981', 65882981, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Energi dan Sumber Daya Mineral', 'Pengawasan Revitalisasi PLTMH Rimba Lestari', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Bandung Barat (Kab.)', 55847800, 'April 2026', 'APBD', 1, 1, '1 Paket', '1) Mengawasi pekerjaan serta produknya, mengawasi ketepatan waktu dan biaya pelaksanaan konstruksi fisik, berikut pembaharuan/ penyesuaian master schedule pelaksanaan (net work planning) sesuai aktual di lapangan; 2) Mengawasi dan mengkoordinasi pekerjaan Sipil, Mekanikal dan Elektrikal dan pekerjaan lain yang berhubungan dengan seluruh penyelesaian proyek tersebut; 3) Mengawasi dan meneliti perubahan-perubahan serta penyesuaian yang terjadi selama pelaksanaan konstruksi fisik; 4) Menyusun Berita Acara dan Persetujuan kemajuan pekerjaan untuk membayar Termin, pemeliharaan pekerjaan serta Serah Terima pekerjaan konstruksi; 5) Mengawasi pelaksanaan pekerjaan konstruksi dari segi kualitas, kuantitas, dan laju pencapaian volume/realisasi fisik; 6) Menyampaikan rekomendasi kepada Pejabat Pembuat Komitmen untuk membuat surat teguran kepada penyedia barang/jasa (kontraktor pelaksana kegiatan ketika terjadi keterlambatan pekerjaan dan/atau ditemukan ketidaksesuaian antara perencanaan dan pelaksanaan di lapangan; 7) Melaksanakan pengawasan secara rutin (day by day) dalam perjalanan pelaksanaan proyek; 8) Mengawasi kebenaran ukuran, kualitas dan kuantitas dari bahan atau komponen bangunan, peralatan, dan perlengkapan selama pekerjaan pelaksanaan di lapangan dan pabrikan mekanikal elektrikal (manufactory); 9) Mengoreksi pekerjaan yang dilaksanakan oleh kontraktor agar sesuai dengan kontrak kerja yang telah disepakati sebelumnya; 10) Memberikan data dan informasi terkait proses pekerjaan di lapangan secara akurat dan dapat dipertanggung jawabkan sesuai dengan kondisi riil di lapangan setiap saat diminta oleh PPK; 11) Melakukan pengawasan pada saat peralatan mekanikal elektrikal dibuat/diperbaiki di pabrikan, serta melakukan pengujian standarisasi turbin sesuai SNI yang disaksikan secara bersama oleh Pabrikan, Kontraktor Pelaksana, Pengawas dan PPK; 12) Melakukan pengawasan pada saat pelaksanaan commissioning test serta Uji Laik Operasi yang disaksikan secara bersama oleh Lembaga Inspeksi Teknis, Kontraktor Pelaksana, Pengawas dan PPK; 13) Menegur/memperingatkan pihak pelaksana pekerjaan jika terjadi penyimpangan terhadap kontrak kerja; 14) Menyelenggarakan rapat – rapat lapangan dan surat – menyurat yang bersangkutan dengan pelaksanaan revitalisasi PLTMH; 15) Membuat laporan harian,mingguan, bulanan terhadap hasil pekerjaan konstruksi yang dilaksanakan oleh Kontraktor Pelaksana; 16) Menyusun daftar kekurangan-kekurangan dan cacat-cacat pekerjaan selama waktu pelaksanaan; 17) Membuat laporan sebelum dan sesudah pekerjaan revitalisasi PLTMH yang telah dilaksanakan; 18) Menyusun laporan akhir pekerjaan pengawasan; 19) Memeriksa dan menyetujui gambar-gambar terlaksana, sesuai dengan fisik pekerjaan yang telah dilaksanakan (as built drawing); 20) Konsultan Pengawas dalam melaksanakan tugasnya akan bertanggungjawab sepenuhnya terhadap kebenaran mutu bahan dan hasil kerja untuk proyek PLTMH, seperti yang telah ditunjuk dalam Dokumen Tender / Kontrak Penyedia. 21) Konsultan Pengawas bersedia sepenuhnya untuk menjelaskan segala sesuatu mengenai pelaksanaan proyek dari awal sampai akhir proyek, bilamana diperlukan oleh pihak-pihak yang berkepentingan (APH) serta dengan dilengkapi pembuatan Final Report seluruh pelaksanaan pekerjaan Pembangunan PLTMH.', '1) Mengawasi pekerjaan serta produknya, mengawasi ketepatan waktu dan biaya pelaksanaan konstruksi fisik, berikut pembaharuan/ penyesuaian master schedule pelaksanaan (net work planning) sesuai aktual di lapangan; 2) Mengawasi dan mengkoordinasi pekerjaan Sipil, Mekanikal dan Elektrikal dan pekerjaan lain yang berhubungan dengan seluruh penyelesaian proyek tersebut; 3) Mengawasi dan meneliti perubahan-perubahan serta penyesuaian yang terjadi selama pelaksanaan konstruksi fisik; 4) Menyusun Berita Acara dan Persetujuan kemajuan pekerjaan untuk membayar Termin, pemeliharaan pekerjaan serta Serah Terima pekerjaan konstruksi; 5) Mengawasi pelaksanaan pekerjaan konstruksi dari segi kualitas, kuantitas, dan laju pencapaian volume/realisasi fisik; 6) Menyampaikan rekomendasi kepada Pejabat Pembuat Komitmen untuk membuat surat teguran kepada penyedia barang/jasa (kontraktor pelaksana kegiatan ketika terjadi keterlambatan pekerjaan dan/atau ditemukan ketidaksesuaian antara perencanaan dan pelaksanaan di lapangan; 7) Melaksanakan pengawasan secara rutin (day by day) dalam perjalanan pelaksanaan proyek; 8) Mengawasi kebenaran ukuran, kualitas dan kuantitas dari bahan atau komponen bangunan, peralatan, dan perlengkapan selama pekerjaan pelaksanaan di lapangan dan pabrikan mekanikal elektrikal (manufactory); 9) Mengoreksi pekerjaan yang dilaksanakan oleh kontraktor agar sesuai dengan kontrak kerja yang telah disepakati sebelumnya; 10) Memberikan data dan informasi terkait proses pekerjaan di lapangan secara akurat dan dapat dipertanggung jawabkan sesuai dengan kondisi riil di lapangan setiap saat diminta oleh PPK; 11) Melakukan pengawasan pada saat peralatan mekanikal elektrikal dibuat/diperbaiki di pabrikan, serta melakukan pengujian standarisasi turbin sesuai SNI yang disaksikan secara bersama oleh Pabrikan, Kontraktor Pelaksana, Pengawas dan PPK; 12) Melakukan pengawasan pada saat pelaksanaan commissioning test serta Uji Laik Operasi yang disaksikan secara bersama oleh 