INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65926550', 65926550, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'IM33 KANTOR WILAYAH DIREKTORAT JENDERAL IMIGRASI SULAWESI BARAT', 'Pengadaan Belanja Pemeliharaan Peralatan Mesin dari Sewa Kendaraan Operasional dan Pemeliharaan Kantor Layanan Perkantoran Kantor Wilayah Direktorat Jenderal Imigrasi Sulawesi Barat TA 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Barat, Mamuju (Kab.)', 54000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'servis berkala, perbaikan ringan/berat (korektif), pergantian suku cadang (ban, oli), pembersihan (cuci), dan pengurusan dokumen kendaraan', '1. Pemeliharaan Rutin (Preventif) oleh Penyewa/Vendor • Servis Berkala: Penggantian oli mesin, filter oli, dan oli transmisi sesuai panduan buku manual. • Cairan Kendaraan: Pengecekan rutin air radiator, minyak rem, oli power steering, dan air accu. • Komponen Mesin: Pemeriksaan busi, filter udara, dan sistem injeksi untuk efisiensi bahan bakar. • Sistem Kelistrikan: Pengecekan baterai/aki, kabel-kabel, dan lampu-lampu agar tidak terjadi mogok. 2. Pemeriksaan Fisik dan Keamanan • Ban dan Kaki-kaki: Rotasi ban, kalibrasi tekanan angin, dan balancing secara berkala. • Sistem Pengereman: Pengecekan ketebalan kampas rem agar aman. • Kebersihan: Menjaga kebersihan interior dan eksterior untuk kenyamanan dan mencegah karat. 3. Tanggung Jawab Selama Masa Sewa • Pengecekan Pasca Sewa: Memastikan kondisi kendaraan tetap prima setelah digunakan. • Penanganan Darurat: Melaporkan jika ada kerusakan dan melakukan perbaikan di bengkel resmi jika diizinkan. • Cara Berkendara: Menghindari cara berkendara agresif (mengerem mendadak, menerabas banjir) yang merusak suspensi dan mesin. 4. Jenis Perawatan Lainnya • Perawatan Non-Rutin: Penggantian spare part, body repair, atau turun mesin jika diperlukan. • Catatan Digital: Menggunakan sistem manajemen armada untuk memantau jadwal servis agar tidak terlewat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2426501);
